  caseStages(lease) {
    return [
      { intro: 'The seller has said yes. Nothing is legally binding yet. Either side can still pull out until exchange.', who: 'You and the estate agent', time: 'A day or two', watch: 'Until exchange the seller can still accept a higher offer. Moving quickly on the next steps is your best protection.' },
      { intro: 'Your broker sends the full mortgage application and your solicitor opens your file. The lender checks your income and spending and sends a valuer.', who: 'You, your broker, the lender, your solicitor', time: '2 to 4 weeks', watch: 'Don’t take on new credit or change jobs now. The lender can check again right up to completion.' },
      { intro: 'An independent surveyor inspects the home’s condition. It’s separate from the lender’s valuation, which only protects the lender.', who: 'Your surveyor', time: 'About a week to book; the report comes a few days later', watch: 'Anything rated 3 is your chance to get quotes and renegotiate. Before exchange, not after.' },
      { intro: 'Your solicitor checks the home’s legal background: council records, flood risk, ' + (lease ? 'the lease and the building’s finances' : 'who owns the land and any old promises tied to it') + ', and the seller’s answers to standard forms. Several documents arrive here: Ara reads each one and flags what’s worth asking.', who: 'Your solicitor, the council, search firms, the seller’s solicitor', time: '4 to 8 weeks. Usually the longest step', watch: '“Not known” answers and missing certificates are the ones to push on. Send your questions together, then chase if you hear nothing for a week.' },
      { intro: 'After the valuation, the lender issues a formal mortgage offer. Your solicitor checks its conditions can be met.', who: 'The lender, your broker, your solicitor', time: 'Usually 2 to 4 weeks after the valuation', watch: 'The offer has an expiry date. Completion has to happen before it, or you’ll need a new offer.' },
      { intro: 'Contracts are swapped and the purchase becomes legally binding. Your deposit is paid and the completion date is fixed.', who: 'You, both solicitors', time: 'The same day, once everyone is ready', watch: 'After exchange, pulling out usually means losing your deposit. Buildings insurance must start today.' },
      { intro: 'The money moves from your lender and solicitor to the seller’s side, and you collect the keys.', who: 'Both solicitors, the lender, the estate agent', time: 'Usually 1 to 4 weeks after exchange', watch: 'Fraudsters target this moment with fake emails changing bank details. Only pay to details you’ve confirmed by phone.' }
    ];
  }
